{
  "headline": "FDA's records trace our protamine sulfate supply to a plant classified OAI 337 days before the shortage posting",
  "headline_cites": ["D3"],
  "sentences": [
    {
      "text": "The protamine sulfate on our labels is manufactured by Fresenius Kabi USA, LLC at FEI 1450022.",
      "cites": ["E11"]
    },
    {
      "text": "FDA inspection 1123748 at that plant ended 2020-05-18 and was classified OAI, with the classification letter dated 2024-05-22, 337 days before FDA posted the shortage on 2021-04-20.",
      "cites": ["D3", "E8"]
    },
    {
      "text": "A second OAI inspection (1174894) ended 2022-06-30, with its classification letter dated 2024-04-30, 436 days after the shortage posting.",
      "cites": ["D4", "E9"]
    },
    {
      "text": "The most recent inspection (1216183) ended 2023-08-24 and was classified VAI.",
      "cites": ["E10"]
    },
    {
      "text": "As of 2026-10-21 the shortage has been on FDA's list for 66 months.",
      "cites": ["D8"]
    },
    {
      "text": "Corvale East holds 293 units at 9.4 per day (31 days on hand) and Corvale General holds 160 units at 10.7 per day (15 days on hand).",
      "cites": ["D1", "D2"]
    },
    {
      "text": "The rule-selected alternate is HF Acquisition Co LLC, DBA HealthFirst, which is not on FDA's shortage list today and its label names no plant we could place.",
      "cites": ["D7"]
    }
  ]
}
